  /* "3 days ago" answers "is this stale" without arithmetic; the exact stamp
     stays on the hover for when the answer is "which morning exactly". */
  function fmtAgo(iso) {
    var t = new Date(iso);
    if (isNaN(t)) return "";
    var mins = Math.round((Date.now() - t.getTime()) / 60000);
    if (mins < 1) return "just now";
    if (mins < 60) return mins + (mins === 1 ? " minute ago" : " minutes ago");
    var hrs = Math.round(mins / 60);
    if (hrs < 24) return hrs + (hrs === 1 ? " hour ago" : " hours ago");
    var days = Math.round(hrs / 24);
    if (days < 7) return days + (days === 1 ? " day ago" : " days ago");
    var wks = Math.round(days / 7);
    if (wks < 5) return wks + (wks === 1 ? " week ago" : " weeks ago");
    return fmtWhen(iso);
  }

  /* The same age in as few characters as it can be said in. The rail is a
     narrow column and "22 minutes ago" was taking a third of the width off
     the line you are meant to be reading. */
  function fmtAgoShort(iso) {
    var t = new Date(iso);
    if (isNaN(t)) return "";
    var mins = Math.round((Date.now() - t.getTime()) / 60000);
    if (mins < 1) return "now";
    if (mins < 60) return mins + "m";
    var hrs = Math.round(mins / 60);
    if (hrs < 24) return hrs + "h";
    var days = Math.round(hrs / 24);
    if (days < 7) return days + "d";
    var wks = Math.round(days / 7);
    if (wks < 5) return wks + "w";
    return fmtWhen(iso);
  }

  function fmtWhen(iso) {
    var d = new Date(iso);
    if (isNaN(d)) return "";
    return d.getDate() + " " + MONTHS[d.getMonth()] + ", " +
      String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
  }

