  /* Which recipe a list is written to. */
  function skillFor(x) {
    var p = String((x && x.platform) || "");
    var sec = String((x && x.section) || "");
    if (sec === "skool" || p === "skool") return SKILLS.skool;
    if (sec === "carousel" || p === "instagram") return SKILLS.carousel;
    if (p === "linkedin") return SKILLS.linkedin;
    if (p === "twitter" || p === "x") return SKILLS.twitter;
    if (p === "facebook") return SKILLS.facebook;
    return null;
  }

  function skillPanel(sk) {
    if (!sk) return "";
    var open = ui.skill === sk.name;
    return '<aside class="skillbox' + (open ? " open" : "") + '">' +
      '<button class="skillhead" data-act="skillopen" data-v="' + esc(sk.name) + '">' +
        '<i class="skillmark">MD</i>' +
        '<span class="skillname">' + esc(sk.name) + "</span>" +
        '<span class="skillhint">' + (open ? "Hide" : "What this post follows") + "</span>" +
      "</button>" +
      (open ? '<div class="skillbody">' + mdLite(sk.body) + "</div>" : "") +
    "</aside>";
  }

  /* Enough markdown for these files and no more: headings, bold, bullets.
     A parser that handles everything is a parser nobody can check. */
  function mdLite(src) {
    var out = [], list = [];
    var flush = function () { if (list.length) { out.push("<ul>" + list.join("") + "</ul>"); list = []; } };
    String(src).split("\n").forEach(function (raw) {
      var line = raw.replace(/\s+$/, "");
      if (!line.trim()) { flush(); return; }
      var bold = function (t) {
        return esc(t).replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
      };
      if (line.indexOf("## ") === 0) { flush(); out.push("<h4>" + esc(line.slice(3)) + "</h4>"); return; }
      if (line.indexOf("# ") === 0) { flush(); out.push("<h3>" + esc(line.slice(2)) + "</h3>"); return; }
      if (line.indexOf("- ") === 0) { list.push("<li>" + bold(line.slice(2)) + "</li>"); return; }
      flush();
      out.push("<p>" + bold(line) + "</p>");
    });
    flush();
    return out.join("");
  }

  /* ---------------- ideas ----------------

     A post starts as a line somebody wrote down, not as a task somebody was
     assigned. So every one of these pages opens on a list of ideas: what it
     is, whose it is, where it is up to. Click one and it opens.

     They live on the video board's document rather than Skool's because this
     shell draws all four pages, and one list read from one place cannot
     disagree with itself. The section says which page an idea belongs to and
     the platform which tab inside it, so the same list serves Content Ideas,
     Written Posts, Carousels and Skool posts without four copies of it. */
  var IDEA_STATUS = [
    { id: "new", label: "Idea", cls: "st-idle" },
    { id: "doing", label: "Being written", cls: "st-work" },
    { id: "review", label: "Ready to check", cls: "st-check" },
    { id: "done", label: "Posted", cls: "st-done" }
  ];
  function ideaStat(id) {
    for (var i = 0; i < IDEA_STATUS.length; i++) if (IDEA_STATUS[i].id === id) return IDEA_STATUS[i];
    return IDEA_STATUS[0];
  }
