  /* The handbook.

     It was one flat numbered list of eleven questions, every answer open at
     once, in a single column of prose you had to read from the top to find
     anything. Nobody read it. Four things fix that: split it by what you are
     actually doing (a recorder never needs the Facebook rules), collapse the
     answers so the page is a list of questions you can scan, put a search
     across all of them at the top, and fold the four reference pages in here
     rather than leaving them as four more lines on the rail.

     Open state is keyed by the question itself, so it survives a re-render
     and a change of tab. */
  function faqKey(f) { return String(f.q).slice(0, 60); }

  function faqSlug(text) {
    return String(text || "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 90)
      .replace(/-+$/g, "");
  }

  function faqHref(topic, slug) {
    return BASE + "/faq/" + encodeURIComponent(topic || "youtube") +
      (slug ? "/" + encodeURIComponent(slug) : "");
  }

  function faqBySlug(topic, slug) {
    var i, f, extras;
    for (i = 0; i < FAQ.length; i++) {
      f = FAQ[i];
      if ((f.topic || "youtube") === topic && faqSlug(f.slug || f.q) === slug) {
        return { key: faqKey(f), target: topic + "-" + slug };
      }
    }
    extras = (FAQ_EXTRAS && FAQ_EXTRAS[topic]) || [];
    for (i = 0; i < extras.length; i++) {
      if (faqSlug(extras[i][1]) === slug) {
        return { key: extras[i][0], target: topic + "-" + slug };
      }
    }
    return null;
  }

  function faqItem(f) {
    var key = faqKey(f);
    var topic = f.topic || "youtube";
    var slug = faqSlug(f.slug || f.q);
    var open = !!(ui.faqOpen || {})[key];
    var more = f.link
      ? '<a class="faq-more" href="' + esc(f.link) + '" target="_blank" rel="noopener">' +
        esc(f.linkLabel) + " \u2197</a>"
      : f.href
        ? '<a class="faq-more" href="' + BASE + esc(f.href) + '">' + esc(f.toLabel) + " \u2192</a>"
      : f.to
        ? '<a class="faq-more" href="' + urlForTab(f.to) + '" data-tab="' + esc(f.to) + '">' +
          esc(f.toLabel) + " \u2192</a>"
        : "";
    var images = (f.images || []).map(function (im) {
      return '<figure class="faq-shot"><a href="' + esc(im.src) + '" target="_blank" rel="noopener">' +
        '<img src="' + esc(im.src) + '" alt="' + esc(im.alt || "") + '" loading="lazy"></a>' +
        (im.caption ? '<figcaption>' + esc(im.caption) + "</figcaption>" : "") + "</figure>";
    }).join("");
    return '<div class="qa' + (open ? " open" : "") + '" id="faq-' + esc(topic + "-" + slug) + '">' +
      '<button class="qa-q" data-act="faq" data-v="' + esc(key) + '" data-faq-topic="' + esc(topic) +
        '" data-faq-slug="' + esc(slug) + '" aria-expanded="' + open + '">' +
        "<span>" + esc(f.q) + "</span><i class=\"qa-chev\" aria-hidden=\"true\"></i>" +
      "</button>" +
      (open ? '<div class="qa-a"><p>' + f.a + "</p>" + images + more + "</div>" : "") +
    "</div>";
  }

  /* A reference page, folded in as one more thing you can open. Closed by
     default like everything else here — the Brand Kit is four screens of
     swatches nobody needs while they are looking up how long a video should
     be. */
  function faqSection(topic, key, title, note, bodyFn) {
    var slug = faqSlug(title);
    var open = !!(ui.faqOpen || {})[key];
    return '<div class="qa qa-big' + (open ? " open" : "") + '" id="faq-' + esc(topic + "-" + slug) + '">' +
      '<button class="qa-q" data-act="faq" data-v="' + esc(key) + '" data-faq-topic="' + esc(topic) +
        '" data-faq-slug="' + esc(slug) + '" aria-expanded="' + open + '">' +
        "<span>" + esc(title) + (note ? '<em>' + esc(note) + "</em>" : "") + "</span>" +
        "<i class=\"qa-chev\" aria-hidden=\"true\"></i>" +
      "</button>" +
      (open ? '<div class="qa-a qa-wide">' + bodyFn() + "</div>" : "") +
    "</div>";
  }

  var FAQ_EXTRAS = {
    youtube: [
      ["pb", "How we make every video", "The whole sequence, start to finish", function () { return playbookPane(); }],
      ["rs", "Recording setup", "Openscreen settings, exactly", function () { return setupPane(); }]
    ],
    kit: [
      ["ac", "Accounts", "The logins we give you \u2014 ask Yar for the passwords", function () { return accountsPane(); }],
      ["bk", "Brand kit", "Colours and reference designs", function () { return brandPane(); }],
      ["vo", "Voice \u2014 ElevenLabs", "The shared account, and how to use it", function () { return voicePane(); }]
    ]
  };

  function faqTopicPane(topic) {
    var q = String(ui.faqQ || "").trim().toLowerCase();
    /* Searching looks everywhere. Somebody typing "thumbnail" wants the
       answer, not the answer if it happens to be filed under the tab they
       are standing on. */
    var list = FAQ.filter(function (f) {
      if (q) return (f.q + " " + f.a).toLowerCase().indexOf(q) >= 0;
      return (f.topic || "youtube") === topic;
    });

    var search =
      '<div class="faq-search">' +
        '<svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">' +
          '<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>' +
        '<input id="faq-q" value="' + esc(String(ui.faqQ || "")) + '" placeholder="Search every answer" aria-label="Search the handbook">' +
        (q ? '<button class="faq-x" data-act="faq-clear" aria-label="Clear">&times;</button>' : "") +
      "</div>";

    if (q && !list.length) {
      return search + '<p class="lede">Nothing matches \u201c' + esc(ui.faqQ) + '\u201d. ' +
        "If the answer you need is not here, ask Yar and it gets added.</p>";
    }

    var extras = (!q && FAQ_EXTRAS[topic]) ? FAQ_EXTRAS[topic] : [];

    return search +
      (q ? '<p class="faq-count">' + list.length + (list.length === 1 ? " answer" : " answers") +
           " across the whole handbook</p>" : "") +
      '<div class="qalist">' + list.map(faqItem).join("") + "</div>" +
      (extras.length
        ? '<div class="faq-more-head">Longer reference</div>' +
          '<div class="qalist">' + extras.map(function (x) {
            return faqSection(topic, x[0], x[1], x[2], x[3]);
          }).join("") + "</div>"
        : "") +
      '<p class="footnote" style="margin-top:26px">If the answer you need is not here, ask Yar and it gets added.</p>';
  }

  /* ---------------- onboarding ----------------
     What somebody new goes through before their first video: one step per
     screen, a few sentences and at most three things to tick, Next and Back.
     It was one long page first, and the note on that was "don't overwhelm" —
     a person on day one does not need the whole board explained to them,
     they need the next thing.

     The profile step reads the profile: a filled field is done, nothing to
     press. Every other tick is pressed and lives on the person's own row
     (pr.onboarding, key → when), so it survives a new browser and an admin
     can see who has read what. Nobody is ever sent here: it is a page on the
     rail that somebody opens if they want it — a team that was already
     working before it existed should not be handed a checklist on sign-in —
     and nothing on the board is gated on it. */
  var OB_STEPS = [
    { id: "welcome", title: "Welcome to the board", nav: "Welcome",
      text: "<p>Seven short steps before your first video: who you are, how the videos work, the voice, the tool that makes the visuals, and where the best examples live.</p>" +
            "<p>Ten minutes to read, and a few things to do along the way. None of it is compulsory, and your place is saved so you can leave and come back.</p>",
      items: [] },
    { id: "profile", title: "Your profile", nav: "Your profile",
      text: "<p>Pay is worked out from your profile and feedback reaches you through it, so it comes first. Each line below ticks itself once the field is filled in on " +
            "<a href=\"__BASE__/profile\" data-tab=\"profile\" data-sub=\"details\">your profile</a>.</p>",
      items: "profile" },
    { id: "videos", title: "How the Videos page works", nav: "The Videos page",
      text: "<p>Every long video is one row on <a href=\"__BASE__/videos/screen-recording\" data-tab=\"board\">Long Videos</a>. It moves left to right through the stages across the top: " +
            "<b>Recording Hooks → Screen Recording → Editing / Hyperframe → Review → Ready to Publish → Published</b>. Hover a stage tile and it tells you what happens there.</p>",
      items: [
        { k: "v-stages", t: "I have opened Videos and read what each stage means." },
        { k: "v-row", t: "I have opened one row and read the hook text, the description and the notes." }
      ] },
    { id: "hooks", title: "The hooks and outros are mine", nav: "Hooks & outros",
      text: "<p>For every video I film the opening hook and the outro before anybody records the middle. A video in <b>Screen Recording</b> has its hooks done and is ready for you; one still in <b>Recording Hooks</b> is not — leave it.</p>" +
            "<p>Watch before you record. My filmed hooks and outros are in the <a href=\"__HOOKS__\" target=\"_blank\" rel=\"noopener\">Hooks and outros folder</a>. " +
            "Your screen recording has to pick up exactly where the hook leaves off and hand over cleanly to the outro — same promise, same tone, no gap, nothing said twice — so the three parts cut together as one take.</p>",
      items: [
        { k: "v-hooks", t: "I have watched the hook and the outro for three videos in Screen Recording." },
        { k: "v-align", t: "I understand the recording has to start where the hook ends and finish where the outro begins." }
      ] },
    { id: "voice", title: "The voice — ElevenLabs", nav: "The voice",
      text: "<p>Every video sounds like me. My voice is already cloned on the shared ElevenLabs account, so you never record a voiceover yourself. The email is under " +
            "<a href=\"__BASE__/faq/kit\" data-tab=\"faq\" data-sub=\"kit\">FAQs → Brand &amp; tools</a>; ask me for the password.</p>" +
            "<p>Voices → My Voices → <b>Yar (High Energy Voice)</b>, model <b>Eleven Multilingual v2</b>. Not v3 — it drifts off my accent. Do not clone a second voice or change the settings on mine, and download the best quality on offer.</p>",
      items: [
        { k: "e-login", t: "I am signed in to the shared ElevenLabs account." },
        { k: "e-voice", t: "I have generated one test line with Yar (High Energy Voice) on Multilingual v2 and listened back." }
      ] },
    { id: "hyperframes", title: "HyperFrames makes the visuals", nav: "HyperFrames",
      text: "<p>A video is an HTML page with timing on it, and HyperFrames renders that page to an MP4: the rail, the cards, the captions that fill in as the words are said. Every short is built with it, and the <b>Editing / Hyperframe</b> stage is where a long video gets its visuals.</p>" +
            "<p>Nothing is animated by hand. The script is written, the voice is recorded, and the composition is built to the real word timings — Claude on the shared account builds it, <code>npm run check</code> validates it, <code>npm run render</code> writes the file. Your job is the brief, the frames and the fixes. " +
            "Docs: <a href=\"https://hyperframes.heygen.com\" target=\"_blank\" rel=\"noopener\">hyperframes.heygen.com</a>. Two finished ones: " +
            "<a href=\"https://www.youtube.com/watch?v=Z7ICqJNchgE\" target=\"_blank\" rel=\"noopener\">AI Video Club</a>, <a href=\"https://www.youtube.com/watch?v=2fZFwMcq_cw\" target=\"_blank\" rel=\"noopener\">Claude Codex Mastery</a>.</p>",
      items: [
        { k: "h-watch", t: "I have watched the two shorts and can point at the rail, the title, the card and the caption." },
        { k: "h-install", t: "I have installed HyperFrames and rendered the example project once." }
      ] },
    { id: "vault", title: "The Vault is the bar", nav: "The Vault",
      text: "<p>The <a href=\"__BASE__/vault\" data-tab=\"vault\" data-sub=\"yt-hooks\">Vault</a> holds the best work we have found — hooks, scripts, carousels, tweets, shorts. It is not your work; it is what yours is measured against. " +
            "For a recorder the two shelves that matter are <b>Youtube Hooks</b> and <b>Shorts Hooks</b>.</p>",
      items: [
        { k: "w-hooks", t: "I have read the Youtube Hooks and Shorts Hooks shelves end to end." },
        { k: "w-scripts", t: "I have read two Youtube Scripts the whole way through." }
      ] },
    { id: "done", title: "That is the list", nav: "Done",
      text: "<p>Open <a href=\"__BASE__/videos/screen-recording\" data-tab=\"board\">Screen Recording</a> and claim a video. Anything you are unsure of is in the <a href=\"__BASE__/faq\" data-tab=\"faq\">FAQs</a>, and if it is not there, ask me and it gets added.</p>",
      items: [] }
  ];

  /* The profile fields the list watches, in the order the profile asks for
     them. Address is one line because it is one thing to have. */
  var OB_PROFILE = [
    { k: "photo", t: "A photo of you.", has: function (pr) { return Boolean(String(pr.avatar || "").trim()); } },
    { k: "email", t: "Your email address.", has: function (pr) { return emailValid(String(pr.email || "").trim()); } },
    { k: "whatsapp", t: "Your WhatsApp number.", has: function (pr) { return Boolean(String(pr.whatsapp || "").trim()); } },
    { k: "iban", t: "Payment details — where your pay goes.", has: function (pr) { return Boolean(String(pr.iban || "").trim()); } },
    { k: "dob", t: "Your date of birth.", has: function (pr) { return Boolean(String(pr.dob || "").trim()); } },
    { k: "address", t: "Your address: street, city, postcode, country.", has: function (pr) {
        return ["street", "city", "postcode", "country"].every(function (f) { return Boolean(String(pr[f] || "").trim()); });
      } }
  ];

  function obTicks() {
    var rec = myRecord();
    var t = rec && rec.pr && rec.pr.onboarding;
    return t && typeof t === "object" ? t : {};
  }
  function obToggle(key) {
    var rec = myRecord();
    if (!rec || ui.readOnly) return false;
    var pr = rec.pr;
    if (!pr.onboarding || typeof pr.onboarding !== "object") pr.onboarding = {};
    if (pr.onboarding[key]) delete pr.onboarding[key];
    else pr.onboarding[key] = new Date().toISOString();
    save();
    return Boolean(pr.onboarding[key]);
  }
  /* The items of one step, each with whether it is done. */
  function obItemsOf(step) {
    var rec = myRecord(), pr = rec ? rec.pr : null, ticks = obTicks();
    if (step.items === "profile") {
      return OB_PROFILE.map(function (f) { return { k: f.k, t: f.t, done: Boolean(pr && f.has(pr)), auto: true }; });
    }
    return step.items.map(function (it) { return { k: it.k, t: it.t, done: Boolean(ticks[it.k]), auto: false }; });
  }
  function obStepDone(step) { return obItemsOf(step).every(function (it) { return it.done; }); }
  /* Done / total across every step, for the bar and the rail. */
  function obProgress() {
    var done = 0, total = 0;
    OB_STEPS.forEach(function (s) { obItemsOf(s).forEach(function (it) { total++; if (it.done) done++; }); });
    return { done: done, total: total };
  }
  /* Where somebody is: the step they chose this session, else the first one
     with something left to do, else the last. */
  function obStepIndex() {
    if (typeof ui.obStep === "number" && ui.obStep >= 0 && ui.obStep < OB_STEPS.length) return ui.obStep;
    /* Nothing done yet means the welcome, not the first thing to tick. */
    if (!obProgress().done) return 0;
    for (var i = 0; i < OB_STEPS.length; i++) if (!obStepDone(OB_STEPS[i])) return i;
    return OB_STEPS.length - 1;
  }
  /* The picture at the top of each step. Drawn here rather than shipped as
     images: they are diagrams of things that change — the stages, the three
     parts of a video, the anatomy of a short — and a PNG of a diagram goes
     stale the week somebody renames a stage. Every colour is a board token,
     so they follow the theme. */
  function obArt(id, pr) {
    function svg(h, body) {
      return '<div class="ob-art"><svg viewBox="0 0 640 ' + h + '" role="img" preserveAspectRatio="xMidYMid meet">' + body + "</svg></div>";
    }
    function box(x, y, w, h, fill, stroke, r) {
      return '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="' + (r == null ? 10 : r) +
        '" fill="' + fill + '" stroke="' + (stroke || "none") + '" stroke-width="1.5"/>';
    }
    function txt(x, y, t, o) {
      o = o || {};
      return '<text x="' + x + '" y="' + y + '" font-size="' + (o.size || 13) + '" font-weight="' + (o.weight || 500) +
        '" fill="' + (o.fill || "var(--text)") + '" text-anchor="' + (o.anchor || "start") +
        (o.mono ? '" font-family="IBM Plex Mono, monospace' : "") + '">' + esc(t) + "</text>";
    }
    var LINE = "var(--line)", SURF = "var(--surface)", ACC = "var(--accent)", OK = "var(--ok-dot)", DIM = "var(--text-dim)", FAINT = "var(--text-faint)";

    if (id === "welcome") {
      /* What the next seven screens are, as a map. */
      var stops = [["Profile", "who you are"], ["Long Videos", "how the board works"], ["Hooks", "mine, filmed first"],
                   ["Voice", "ElevenLabs"], ["HyperFrames", "the visuals"], ["Vault", "the bar"]];
      return svg(170,
        '<line x1="52" y1="56" x2="588" y2="56" stroke="' + LINE + '" stroke-width="2"/>' +
        stops.map(function (st, i) {
          var x = 52 + i * 107.2;
          return '<circle cx="' + x + '" cy="56" r="13" fill="' + (i === 0 ? ACC : SURF) + '" stroke="' + (i === 0 ? ACC : LINE) + '" stroke-width="2"/>' +
            txt(x, 61, String(i + 1), { anchor: "middle", size: 12, weight: 600, fill: i === 0 ? "var(--accent-ink)" : DIM }) +
            txt(x, 92, st[0], { anchor: "middle", size: 13, weight: 600 }) +
            txt(x, 110, st[1], { anchor: "middle", size: 11, fill: FAINT });
        }).join("") +
        box(52, 130, 536, 30, "var(--accent-wash)", "var(--accent-line)", 15) +
        txt(320, 150, "Seven screens · about ten minutes · nothing here is compulsory", { anchor: "middle", size: 12.5, fill: DIM }));
    }

    if (id === "profile") {
      /* Your own card, with the rows you have actually filled in ticked —
         the picture is the progress, so there is nothing to read twice. */
      /* Short labels: the card is 360 wide, and the checklist below
         already carries the detail. */
      var rows = OB_PROFILE.map(function (f) {
        return { t: f.t.split(/[:—]/)[0].trim().replace(/\.$/, ""), done: Boolean(pr && f.has(pr)) };
      });
      var av = Boolean(pr && String(pr.avatar || "").trim());
      return svg(190,
        box(140, 14, 360, 162, SURF, LINE, 14) +
        '<circle cx="176" cy="48" r="20" fill="' + (av ? OK : "var(--idle-wash)") + '" stroke="' + (av ? OK : LINE) + '" stroke-width="1.5"/>' +
        (av ? '<path d="M168 48l6 6 12-12" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>'
            : '<circle cx="176" cy="43" r="6" fill="' + FAINT + '"/><path d="M165 60a11 11 0 0 1 22 0z" fill="' + FAINT + '"/>') +
        txt(208, 45, pr && pr.name ? pr.name : "Your name", { size: 14, weight: 600 }) +
        txt(208, 62, "the board reaches you here", { size: 11, fill: FAINT }) +
        rows.slice(1).map(function (r, i) {
          var y = 84 + i * 19;
          return '<rect x="160" y="' + y + '" width="320" height="14" rx="7" fill="' + (r.done ? "var(--ok-wash)" : "var(--idle-wash)") + '"/>' +
            '<circle cx="169" cy="' + (y + 7) + '" r="5" fill="' + (r.done ? OK : "transparent") + '" stroke="' + (r.done ? OK : LINE) + '" stroke-width="1.5"/>' +
            (r.done ? '<path d="M166.6 ' + (y + 7) + 'l1.8 1.9 3.4-3.6" fill="none" stroke="#fff" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>' : "") +
            txt(182, y + 11, r.t, { size: 11, fill: r.done ? DIM : FAINT });
        }).join(""));
    }

    if (id === "videos") {
      /* The stages, in their own colours, with the one you work in lit. */
      var st = [["Hooks", "var(--line-strong)"], ["Screen rec.", "var(--warn-dot)"], ["Editing", "var(--accent-bright)"],
                ["Review", OK], ["Ready", "var(--accent)"], ["Published", "var(--ok-dot)"]];
      return svg(150,
        st.map(function (x, i) {
          var bx = 14 + i * 104, on = i === 1;
          return box(bx, 40, 90, 54, on ? "var(--accent-wash)" : SURF, on ? ACC : LINE, 10) +
            '<rect x="' + bx + '" y="40" width="90" height="4" rx="2" fill="' + x[1] + '"/>' +
            txt(bx + 45, 72, x[0], { anchor: "middle", size: 11.5, weight: on ? 700 : 500, fill: on ? "var(--text)" : DIM }) +
            (i < 5 ? '<path d="M' + (bx + 94) + ' 67l7 0m-3 -3l3 3l-3 3" stroke="' + LINE + '" stroke-width="1.6" fill="none" stroke-linecap="round"/>' : "");
        }).join("") +
        txt(59, 30, "yours to leave", { anchor: "middle", size: 10.5, fill: FAINT }) +
        txt(163, 30, "yours to record", { anchor: "middle", size: 10.5, weight: 600, fill: "var(--accent)" }) +
        box(14, 108, 612, 28, "var(--idle-wash)", "none", 14) +
        txt(320, 126, "One video is one row, and it moves left to right", { anchor: "middle", size: 12, fill: DIM }));
    }

    if (id === "hooks") {
      /* The three parts, and the two seams that have to disappear. */
      return svg(180,
        box(14, 34, 150, 52, "var(--accent-wash)", ACC, 10) + txt(89, 58, "HOOK", { anchor: "middle", size: 12.5, weight: 700 }) +
          txt(89, 75, "filmed by Yar", { anchor: "middle", size: 10.5, fill: DIM }) +
        box(170, 34, 300, 52, "var(--ok-wash)", OK, 10) + txt(320, 58, "YOUR SCREEN RECORDING", { anchor: "middle", size: 12.5, weight: 700 }) +
          txt(320, 75, "the middle of the video", { anchor: "middle", size: 10.5, fill: DIM }) +
        box(476, 34, 150, 52, "var(--accent-wash)", ACC, 10) + txt(551, 58, "OUTRO", { anchor: "middle", size: 12.5, weight: 700 }) +
          txt(551, 75, "filmed by Yar", { anchor: "middle", size: 10.5, fill: DIM }) +
        '<path d="M167 26v68M473 26v68" stroke="' + ACC + '" stroke-width="1.5" stroke-dasharray="3 3"/>' +
        txt(167, 18, "no gap", { anchor: "middle", size: 10.5, fill: "var(--accent)" }) +
        txt(473, 18, "no repeat", { anchor: "middle", size: 10.5, fill: "var(--accent)" }) +
        '<path d="M14 108h612" stroke="' + LINE + '" stroke-width="1.5"/>' +
        '<path d="M14 104v8M626 104v8" stroke="' + LINE + '" stroke-width="1.5"/>' +
        txt(320, 100, "cut together it has to sound like one take", { anchor: "middle", size: 12, fill: DIM }) +
        box(170, 126, 300, 30, SURF, LINE, 15) +
        txt(320, 146, "Screen Recording = hooks are done, take it", { anchor: "middle", size: 12, weight: 600, fill: OK }));
    }

    if (id === "voice") {
      var bars = "";
      for (var i = 0; i < 46; i++) {
        var hh = 6 + Math.round(30 * Math.abs(Math.sin(i * 0.9)) * (0.5 + 0.5 * Math.abs(Math.cos(i * 0.31))));
        bars += '<rect x="' + (196 + i * 9) + '" y="' + (62 - hh / 2) + '" width="4" height="' + hh + '" rx="2" fill="' + ACC + '" opacity="' + (0.35 + 0.5 * Math.abs(Math.sin(i * 0.5))).toFixed(2) + '"/>';
      }
      return svg(170,
        box(14, 26, 166, 72, SURF, LINE, 12) +
        '<circle cx="46" cy="62" r="17" fill="var(--accent-wash)" stroke="' + ACC + '" stroke-width="1.5"/>' +
        '<path d="M46 54v10m-5-7v4m10-4v4" stroke="' + ACC + '" stroke-width="2" stroke-linecap="round"/>' +
        txt(72, 58, "Yar", { size: 12.5, weight: 700 }) + txt(72, 74, "High Energy Voice", { size: 10.5, fill: DIM }) +
        bars +
        box(14, 116, 300, 34, "var(--ok-wash)", OK, 8) +
        '<path d="M32 133l6 6 12-13" fill="none" stroke="' + OK + '" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>' +
        txt(60, 138, "Eleven Multilingual v2 — use this", { size: 12, weight: 600 }) +
        box(326, 116, 300, 34, "var(--bad-wash)", "none", 8) +
        '<path d="M344 127l12 12m0-12l-12 12" stroke="var(--bad)" stroke-width="2.4" stroke-linecap="round"/>' +
        txt(372, 138, "v3 — drifts off the accent", { size: 12, weight: 600, fill: "var(--bad)" }));
    }

    if (id === "hyperframes") {
      /* The anatomy of one short, next to what comes out of it. */
      var fx = 232, fy = 12, fw = 118, fh = 148;
      return svg(180,
        box(fx, fy, fw, fh, SURF, LINE, 12) +
        '<rect x="' + (fx + 12) + '" y="' + (fy + 16) + '" width="94" height="4" rx="2" fill="' + LINE + '"/>' +
        '<rect x="' + (fx + 12) + '" y="' + (fy + 16) + '" width="52" height="4" rx="2" fill="' + ACC + '"/>' +
        box(fx + 12, fy + 28, 94, 22, "var(--surface)", LINE, 6) +
        '<rect x="' + (fx + 18) + '" y="' + (fy + 34) + '" width="42" height="4" rx="2" fill="var(--text)"/>' +
        '<rect x="' + (fx + 18) + '" y="' + (fy + 42) + '" width="30" height="4" rx="2" fill="' + ACC + '"/>' +
        box(fx + 12, fy + 56, 94, 56, "var(--accent-wash)", "var(--accent-line)", 8) +
        '<rect x="' + (fx + 24) + '" y="' + (fy + 122) + '" width="70" height="5" rx="2.5" fill="' + ACC + '"/>' +
        '<rect x="' + (fx + 36) + '" y="' + (fy + 132) + '" width="46" height="5" rx="2.5" fill="' + LINE + '"/>' +
        /* labels, left and right */
        txt(222, fy + 22, "progress rail", { anchor: "end", size: 11, fill: DIM }) +
        txt(222, fy + 44, "title", { anchor: "end", size: 11, fill: DIM }) +
        txt(360, fy + 88, "card — the visual", { size: 11, fill: DIM }) +
        txt(360, fy + 130, "caption, on the word", { size: 11, fill: DIM }) +
        '<path d="M224 ' + (fy + 18) + 'h' + (fx - 226) + 'M224 ' + (fy + 40) + 'h' + (fx - 226) + '" stroke="' + LINE + '" stroke-width="1.2"/>' +
        '<path d="M' + (fx + fw + 2) + ' ' + (fy + 84) + 'h22M' + (fx + fw + 2) + ' ' + (fy + 126) + 'h22" stroke="' + LINE + '" stroke-width="1.2"/>' +
        box(14, 152, 612, 26, "var(--idle-wash)", "none", 13) +
        txt(320, 169, "script → voice → composition built to the real word timings → render", { anchor: "middle", size: 12, fill: DIM }));
    }

    if (id === "vault") {
      var shelf = [["Youtube Hooks", "the first thirty seconds", true], ["Shorts Hooks", "the first two", true],
                   ["Youtube Scripts", "open, turn, close", false], ["Carousels · Tweets · Skool", "everything else", false]];
      return svg(200,
        shelf.map(function (r, i) {
          var y = 14 + i * 40;
          return box(70, y, 500, 32, r[2] ? "var(--accent-wash)" : SURF, r[2] ? "var(--accent-line)" : LINE, 8) +
            '<rect x="70" y="' + y + '" width="4" height="32" rx="2" fill="' + (r[2] ? ACC : LINE) + '"/>' +
            txt(90, y + 20, r[0], { size: 12.5, weight: r[2] ? 700 : 500, fill: r[2] ? "var(--text)" : DIM }) +
            txt(556, y + 20, r[1], { anchor: "end", size: 11, fill: FAINT });
        }).join("") +
        txt(320, 192, "not your work — what yours is measured against", { anchor: "middle", size: 12, fill: DIM }));
    }

    /* done */
    return svg(160,
      '<circle cx="320" cy="56" r="30" fill="var(--ok-wash)" stroke="' + OK + '" stroke-width="2"/>' +
      '<path d="M306 56l10 10 20-21" fill="none" stroke="' + OK + '" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/>' +
      txt(320, 110, "You are set up", { anchor: "middle", size: 15, weight: 700 }) +
      txt(320, 132, "open Screen Recording and claim a video", { anchor: "middle", size: 12, fill: DIM }));
  }

  function onboardingPane() {
    if (!who.signedIn) return '<p class="lede">Sign in to see the steps.</p>';
    var rec = myRecord();
    var pr = rec ? rec.pr : null;
    var n = obStepIndex();
    var step = OB_STEPS[n];
    var items = obItemsOf(step);
    var p = obProgress();
    var canTick = Boolean(rec) && !ui.readOnly;
    var last = n === OB_STEPS.length - 1;
    var text = step.text.replace(/__BASE__/g, BASE).replace(/__HOOKS__/g, HOOKS_DRIVE);
    var pct = p.total ? Math.round(100 * p.done / p.total) : 0;

    /* The steps down the left: where you are, what is behind you, what is
       still to come. On a narrow screen it becomes the row of dots. */
    var steps = '<ol class="ob-steps" aria-label="Steps">' + OB_STEPS.map(function (st, i) {
      var hasItems = obItemsOf(st).length > 0;
      var done = hasItems && obStepDone(st), on = i === n;
      return '<li><button class="ob-step' + (on ? " on" : "") + (done ? " done" : "") + '" data-act="ob-go" data-v="' + i + '"' +
        (on ? ' aria-current="step"' : "") + '>' +
        '<span class="ob-step-n">' + (done && !on ? "\u2713" : String(i + 1)) + "</span>" +
        '<span class="ob-step-t">' + esc(st.nav || st.title) + "</span></button></li>";
    }).join("") + "</ol>";

    var list = items.length
      ? '<ul class="ob-list">' + items.map(function (it) {
          return '<li class="ob-item' + (it.done ? " done" : "") + '">' +
            (it.auto
              ? '<span class="ob-box auto" aria-hidden="true">' + (it.done ? "\u2713" : "") + "</span>"
              : '<button class="ob-box" data-act="ob-tick" data-v="' + esc(it.k) + '" role="checkbox" aria-checked="' + (it.done ? "true" : "false") + '"' +
                  (canTick ? "" : " disabled") + ">" + (it.done ? "\u2713" : "") + "</button>") +
            "<p>" + it.t + "</p></li>";
        }).join("") + "</ul>"
      : "";

    var notice = !rec
      ? '<div class="banner warn"><b>Start your profile first.</b><span>Your ticks are saved on your own row, and there is no row under ' +
          esc(who.name || "your name") + " yet. " +
          (ui.readOnly ? "Ask Yar for edit access." : '<button class="btn btn-sm" data-act="pmine">Start my profile</button>') + "</span></div>"
      : ui.readOnly ? '<div class="banner info"><b>View only.</b><span>You can read the steps, but ticking needs edit access \u2014 ask Yar.</span></div>' : "";

    var left = items.filter(function (it) { return !it.done; }).length;
    var nav = '<div class="ob-nav">' +
      (n > 0 ? '<button class="btn" data-act="ob-go" data-v="' + (n - 1) + '">\u2190 Back</button>' : "<span></span>") +
      (!items.length ? '<span class="ob-left"></span>'
        : left ? '<span class="ob-left">' + left + (left === 1 ? " line" : " lines") + " left here</span>"
        : '<span class="ob-left ok">this one is done</span>') +
      (last
        ? '<a class="btn btn-primary" href="' + BASE + '/videos/screen-recording" data-tab="board">Go to Screen Recording</a>'
        : '<button class="btn btn-primary" data-act="ob-go" data-v="' + (n + 1) + '">Next \u2192</button>') +
      "</div>";

    return '<div class="ob">' +
      '<aside class="ob-side">' +
        '<div class="ob-ring">' +
          '<svg viewBox="0 0 72 72" aria-hidden="true">' +
            '<circle cx="36" cy="36" r="31" fill="none" stroke="var(--line)" stroke-width="7"/>' +
            '<circle cx="36" cy="36" r="31" fill="none" stroke="var(--accent)" stroke-width="7" stroke-linecap="round" ' +
              'stroke-dasharray="' + (1.948 * pct).toFixed(1) + ' 999" transform="rotate(-90 36 36)"/>' +
          "</svg>" +
          "<b>" + p.done + "<i>/" + p.total + "</i></b>" +
        "</div>" +
        '<p class="ob-side-note">' + (p.done >= p.total ? "All done \u2014 nothing left." : "Done at your own pace. Nothing here is compulsory.") + "</p>" +
        steps +
      "</aside>" +
      '<section class="ob-main">' +
        '<p class="eyebrow">Step ' + (n + 1) + " of " + OB_STEPS.length + "</p>" +
        "<h2>" + esc(step.title) + "</h2>" +
        obArt(step.id, pr) +
        '<div class="ob-text">' + text + "</div>" +
        notice + list + nav +
      "</section>" +
    "</div>";
  }

  function playbookPane() {
    /* The four groups are a sequence, not four unrelated lists, so they
       read as numbered phases on a rail. The goal moves to the top: it is
       the reason the rest exists, and it was buried at the bottom. */
    return (
      '<p class="lede" style="margin-bottom:24px">Everything a recorder needs, start to finish. Read it once before your first video, then use the board.</p>' +

      '<div class="goalcard">' +
        '<div class="eyebrow">Why the channel exists</div>' +
        '<p>' + linkify(GOAL_TEXT) + "</p>" +
        '<a class="btn btn-primary btn-sm" href="' + SKOOL + '" target="_blank" rel="noopener">Open the Skool community</a>' +
      "</div>" +

      '<ol class="phases">' + PLAYBOOK.map(function (g, i) {
        return '<li class="phase">' +
          '<div class="phase-mark">' + (i + 1) + "</div>" +
          '<div class="phase-body">' +
            '<div class="phase-head"><h2>' + esc(g.h) + "</h2>" +
              (g.note ? '<span class="phase-note">' + esc(g.note) + "</span>" : "") + "</div>" +
            '<ol class="steps card">' + g.items.map(function (t) {
              return '<li class="step"><p>' + linkify(t) + "</p></li>";
            }).join("") + "</ol>" +
          "</div>" +
        "</li>";
      }).join("") + "</ol>" +

      '<p class="footnote">Recording settings, brand colours and the voice account live on their own tabs.</p>'
    );
  }

  function setupPane() {
    return (
      '<p class="lede" style="margin-bottom:24px">We record and edit in Openscreen. These are the exact settings — match them so every video on the channel looks like the same channel.</p>' +
      sec("The tool", "Free and open source.",
        '<div class="linklist">' +
          '<div class="linkitem"><span class="nm">Openscreen</span><a class="u" href="https://getopenscreen.com/" target="_blank" rel="noopener">getopenscreen.com</a></div>' +
          '<div class="linkitem"><span class="nm">Source code</span><a class="u" href="https://github.com/getopenscreen/openscreen/tree/main" target="_blank" rel="noopener">github.com/getopenscreen/openscreen</a></div>' +
        "</div>") +
      sec("Final video has to look like this", "Blue ground, rounded window, generous padding.", figure("final_look", "Reference frame — padded, rounded screen recording on the blue background with the green cursor.")) +
      sec("Export settings", "Set these in the Composition panel.",
        '<div class="grid2"><div><div class="kv">' + EXPORT_SETTINGS.map(function (r) {
          return '<div class="k">' + esc(r[0]) + '</div><div class="v">' +
            (r[1].charAt(0) === "#" ? '<span style="display:inline-block;width:14px;height:14px;border-radius:4px;background:' + r[1] + ';border:1px solid var(--line)"></span>' : "") +
            '<span class="' + (r[1].charAt(0) === "#" ? "mono" : "") + '">' + esc(r[1]) + "</span></div>";
        }).join("") + "</div></div>" + figure("comp_panel", "Composition panel — keep Format on Original.", true) + "</div>") +
      sec("Cursor", "Green cursor, clipped to canvas.", '<div class="grid2">' + figure("cursor_panel", "Cursor panel — the green cursor style, size 9.6.", true) + '<div class="callout" style="align-self:start"><div class="eyebrow">Why it matters</div><p>The green cursor is the one thing viewers track for the whole video. Show cursor on, clip to canvas on, and leave smoothing and motion blur at zero.</p></div>' + "</div>") +
      sec("Timeline editing", "What to do after the take.",
        '<ul class="bullets"><li>Add zooms</li><li>Trimming</li><li>Speed</li><li>Annotations</li></ul>' + figure("timeline", "Timeline — zoom keyframes and annotations on the recording track.")) +
      sec("Our branding", "Use more of these colours.", figure("skool_brand", "The Skool community page — the blue and yellow the videos should echo."))
    );
  }

  function brandPane() {
    var swatch = function (name, hex) {
      return '<div class="swatch"><div class="fill" style="background:' + hex + '"></div>' +
        '<div class="meta"><span class="nm">' + esc(name) + '</span>' +
        '<button class="hx" data-act="copy" data-v="' + hex + '" title="Copy hex">' + hex + "</button></div></div>";
    };
    return (
      '<p class="lede" style="margin-bottom:24px">Copy these, or hand them to the AI when you make slides, websites or dashboards.</p>' +
      sec("Colours", "Click a hex to copy it.", '<div class="swatches">' + swatch("Blue", "#0065DD") + swatch("Yellow", "#FFDC00") + swatch("Recording background", "#3b82f6") + "</div>") +
      sec("Thumbnails", "The look for anything that fronts a video.",
        '<div class="grid2">' + figure("thumb_ccm", "Claude Codex Mastery — blue ground, yellow highlight block, whiteboard breakdown.") +
        figure("thumb_perfect", "Perfect Business — same system, numbered hand-drawn list.") + "</div>") +
      sec("Dashboard design", "One product, three grounds.",
        '<div class="grid3">' + figure("dash_light", "Light") + figure("dash_cream", "Warm") + figure("dash_dark", "Dark") + "</div>") +
      sec("Website design", "Marketing pages in the same family.",
        '<div class="grid2">' + figure("site_hero", "Hero — restrained type, live-data panel on the right.") + figure("site_shot", "The same page in the browser.") + "</div>") +
      sec("Slides design", "For anything explanatory.",
        '<div class="grid2">' + figure("slide_design", "Chaptered slide — running order, one big claim, numbers as cards.") +
        figure("slide_ccm", "On-camera slide — numbered path across a blue board.") + "</div>")
    );
  }

  function payPane() {
    return (
      '<div class="payhead">' +
        '<div class="eyebrow">Per video</div>' +
        '<div class="paytag">500\u20131200 PKR<span>most videos land at 650\u2013850</span></div>' +
        '<div class="payscale">' +
          '<div class="payscale-bar"></div>' +
          '<div class="payscale-ends">' +
            "<span><b>500</b> short, surface level</span>" +
            "<span><b>1200</b> genuinely exceptional</span>" +
          "</div>" +
        "</div>" +
      "</div>" +

      sec("The real money is in views", "Every video keeps earning as it grows.",
        '<div class="payplus">' + PAY_ABOVE.map(function (f) {
          return '<div class="payplus-item"><div class="payplus-k">' + esc(f.k) + "</div>" +
            "<p>" + esc(f.d) + "</p></div>";
        }).join("") + "</div>") +

      sec("What decides the number", "Three things, in this order.",
        '<div class="factors">' + PAY_FACTORS.map(function (f, i) {
          return '<div class="factor">' +
            '<div class="factor-n">' + String(i + 1).padStart(2, "0") + "</div>" +
            '<div class="factor-b"><h3>' + esc(f.k) + "</h3><p>" + esc(f.d) + "</p></div>" +
          "</div>";
        }).join("") + "</div>") +

      /* The three factors above are what somebody decided the number should
         depend on. This is the arithmetic that actually runs. Both belong
         here: the first says what is being judged, the second says what the
         board does with the judgement, and a team told only the first cannot
         check the second. */
      sec("The sum, exactly as the board runs it",
        "Nothing here is a rule of thumb \u2014 this is the arithmetic, and every video's own working is on your Arrears page.",
        '<ol class="algo">' +
          '<li class="algo-step"><div class="algo-k">Start from the mark</div>' +
            '<div class="algo-v mono">quality curve, not a straight line</div>' +
            "<p>Yar\u2019s score out of 10 where he has given one, the analyser\u2019s reading of the " +
            "script until then. A 7 is about 650, an 8 about 800, and anything below 9 is capped " +
            "at 850. The curve only opens the exceptional band once the work is exceptional.</p></li>" +
          '<li class="algo-step"><div class="algo-k">No mark yet?</div>' +
            '<div class="algo-v mono">' + PAY_MIN + " PKR</div>" +
            "<p>The video sits at the floor until somebody scores it. The analyser reads the " +
            "script, so a video with no transcript on it has no mark of either kind and cannot " +
            "move off the floor. <b>That is a review waiting to happen, not a verdict</b> \u2014 " +
            "and it is the single biggest thing worth chasing, because it is worth hundreds.</p></li>" +
          '<li class="algo-step"><div class="algo-k">Then length</div>' +
            '<div class="algo-v mono">\u00d7' + LEN_MAX_F.toFixed(2) + " at " + LEN_GOAL + " min+</div>" +
            "<p>At " + LEN_GOAL + " minutes and over the sum is multiplied by " + LEN_MAX_F.toFixed(2) +
            "; at " + LEN_FLOOR + " it is unchanged; below " + LEN_FLOOR + " it falls with the " +
            "length and stops at \u00d7" + LEN_MIN_F.toFixed(2) + ". No length recorded means no " +
            "adjustment \u2014 an unknown is not a penalty. A reel is never measured on length. " +
            "Length cannot lift an ordinary score above 850.</p></li>" +
          '<li class="algo-step"><div class="algo-k">Then rounding</div>' +
            '<div class="algo-v mono">nearest ' + PAY_STEP + "</div>" +
            "<p>So the figure is always a round number.</p></li>" +
          '<li class="algo-step bad"><div class="algo-k">Then two deductions</div>' +
            '<div class="algo-v mono">\u2212' + PEN_SHORT + " and \u2212" + PEN_LOW + "</div>" +
            "<p>\u2212" + PEN_SHORT + " if the video runs under " + PEN_SHORT_MINS + " minutes. " +
            "\u2212" + PEN_LOW + " if the analyser marks the script under " + PEN_LOW_SCORE + ". " +
            "Both can land on the same video, and they come off after the length factor rather " +
            "than instead of it.</p></li>" +
          '<li class="algo-step good"><div class="algo-k">Then Yar decides</div>' +
            '<div class="algo-v">the last word</div>' +
            "<p>The formula has no idea what a topic cost to wrestle into working \u2014 the second " +
            "factor above \u2014 so Yar can adjust it. Every adjustment must still stay inside " +
            "500\u20131,200, and more than 850 is for genuinely exceptional work.</p></li>" +
        "</ol>" +
        '<p class="footnote">Views are not in this sum. The bonuses above follow the view count ' +
          "long after the video is posted.</p>") +

      /* The scorecard, published. It decides the mark, the mark decides most
         of the number, and until now the only way to see any of it was to
         open one video's AI Score tab and infer the rules from one reading.
         Weighted order, because that is the order worth working in. */
      sec("What the analyser measures, and what each is worth",
        "Nine readings off the script, weighted. This is the whole scorecard \u2014 in the order worth working on.",
        '<div class="scorecard">' + SCORECARD.map(function (spec) {
          return '<div class="sc-row">' +
            '<div class="sc-w"><b>' + spec.weight + "%</b><i>of the mark</i></div>" +
            '<div class="sc-b">' +
              "<h3>" + esc(spec.label) + "</h3>" +
              "<p>" + esc(spec.plain) + "</p>" +
              '<div class="sc-rule"><span>How it is scored</span>' + esc(spec.rule) + "</div>" +
              '<div class="sc-fix"><span>' + esc(spec.fix) + "</span>" + esc(spec.how) + "</div>" +
            "</div>" +
          "</div>";
        }).join("") + "</div>" +
        '<p class="footnote">The nine are averaged by weight. A reading that cannot be taken \u2014 ' +
          "pacing on a transcript with no punctuation, say \u2014 drops out of the average rather " +
          "than scoring zero, because a missing measurement is not a bad one. Every video\u2019s " +
          "own readings are on its <b>AI Score</b> tab, with the lines that produced them.</p>") +

      sec("What counts", "A video only earns if we can use it.",
        '<ul class="bullets">' + PAY_BAR.map(function (t) {
          return "<li>" + linkify(t) + "</li>";
        }).join("") + "</ul>") +

      sec("Volume and full-time", "",
        '<ul class="bullets">' + PAY_VOLUME.map(function (t) {
          return "<li>" + linkify(t) + "</li>";
        }).join("") + "</ul>")
    );
  }

  /* Where a channel is. Read off the address for the ones already stored,
     so the split appeared without anything being rewritten — a youtube.com
     link is a YouTube channel whatever else is true about it. */
  function cmpById(id) {
    var all = state.competitors || [];
    for (var i = 0; i < all.length; i++) if (String(all[i].id) === String(id)) return all[i];
    return null;
  }
  /* Two tabs folded into one each.

     X and Twitter were separate tabs for the same website, and a competitor
     filed under one was invisible on the other. Reels was a tab of YouTube
     channels. Both old names are mapped here rather than rewritten in the
     stored rows: nothing filed under them is stranded, and the data still
     says what somebody actually chose. */
  function normPlat(p) {
    p = String(p || "");
    if (p === "x") return "twitter";
    if (p === "reels") return "youtube";
    /* The Vault's shelves are named for what is on them, not for the network
       they came off. Without this they all fell through to the YouTube play
       button, so a LinkedIn carousel was marked with a red rectangle. */
    if (p === "li-carousels") return "linkedin";
    if (p === "yt-hooks" || p === "yt-scripts") return "youtube";
    if (p === "sh-hooks" || p === "sh-scripts") return "youtube";
    return p;
  }
  function cmpPlatform(c) {
    if (c && c.platform) return normPlat(c.platform);
    var u = String((c && c.u) || "").toLowerCase();
    if (u.indexOf("linkedin.") >= 0) return "linkedin";
    if (u.indexOf("instagram.") >= 0) return "instagram";
    if (u.indexOf("tiktok.") >= 0) return "tiktok";
    if (u.indexOf("skool.com") >= 0) return "skool";
    if (u.indexOf("x.com") >= 0 || u.indexOf("twitter.") >= 0) return "twitter";
    return "youtube";
  }
  /* A competitor's community tag, or "" when nobody has filed it yet. Kept to
     the two ids and nothing else, so a typo in a stored row cannot invent a
     third community that no chip ever shows. */
  function cmpTagId(t) {
    t = String(t || "").toLowerCase();
    return t === "ccm" || t === "avc" ? t : "";
  }
  function cmpTag(c) { return cmpTagId(c && c.tag); }
  function cmpTagOf(id) {
    for (var i = 0; i < CMP_TAGS.length; i++) if (CMP_TAGS[i].id === id) return CMP_TAGS[i];
    return null;
  }
  /* Whether a row belongs under the filter that is on. With nothing
     selected everything shows, which is also the only place an unfiled row
     can be seen — so an admin can find it and file it. */
  function cmpTagOk(c) { return !ui.cmpTag || cmpTag(c) === ui.cmpTag; }

  /* The strip over the platform tabs: All, CCM, AVC, each with how many rows
     it holds across every platform. One filter for the whole page rather
     than one per tab, because the question "who are we up against for AI
     Video Club" is the same question on YouTube as on Instagram. */
  function cmpTagBar() {
    var all = state.competitors || [];
    var count = { "": all.length };
    CMP_TAGS.forEach(function (t) {
      count[t.id] = all.filter(function (c) { return cmpTag(c) === t.id; }).length;
    });
    var chips = [{ id: "", label: "All", name: "Both communities" }].concat(CMP_TAGS);
    var on = cmpTagOf(ui.cmpTag);
    return '<div class="cmptagbar" role="group" aria-label="Which community">' +
      '<span class="cmptag-kicker">Competitors to</span>' +
      chips.map(function (t) {
        var active = (ui.cmpTag || "") === t.id;
        return '<button class="chip" aria-pressed="' + active + '" data-act="cmptag" data-v="' + esc(t.id) + '" title="' + esc(t.name) + '">' +
          esc(t.label) + ' <span class="n">' + count[t.id] + "</span></button>";
      }).join("") +
      (on ? '<span class="cmptag-what">' + esc(on.name) + " — " + esc(on.what) + "</span>" : "") +
      "</div>";
  }

  /* The CCM | AVC switch on a row. Two buttons rather than a select so the
     choice is read at a glance down the list, and so an unfiled row shows as
     neither lit. */
  function cmpTagSwitch(c) {
    var cur = cmpTag(c);
    return '<span class="tagseg" role="group" aria-label="Community">' + CMP_TAGS.map(function (t) {
      return '<button class="tagseg-b' + (cur === t.id ? " on" : "") + '" data-act="ctag" data-c="' + esc(c.id) +
        '" data-v="' + t.id + '" title="' + esc(t.name) + '" aria-pressed="' + (cur === t.id) + '">' + esc(t.label) + "</button>";
    }).join("") + "</span>";
  }
  /* The read-only mark of the same thing. */
  function cmpTagBadge(c) {
    var t = cmpTagOf(cmpTag(c));
    return t ? '<span class="tagbadge ' + t.id + '" title="' + esc(t.name) + '">' + esc(t.label) + "</span>" : "";
  }

  var CMP_LABEL = { youtube: "YouTube", reels: "Reels", linkedin: "LinkedIn", instagram: "Instagram", skool: "Skool", x: "X",
                    twitter: "Twitter", facebook: "Facebook", tiktok: "TikTok",
                    /* The Vault's own shelves. */
                    "yt-hooks": "YouTube hook", "yt-scripts": "YouTube script",
                    "li-carousels": "LinkedIn carousel",
                    "sh-hooks": "Shorts hook", "sh-scripts": "Shorts script" };

  /* The mark beside a name, drawn per platform.

     Every one of these rows used to carry the YouTube play button whatever
     site it pointed at, so the Instagram list was a column of little red
     rectangles. Inline SVG rather than CSS shapes: these are brand marks,
     they have to survive being 15px, and one function is easier to keep
     right than five stacked pseudo-elements. */
  function platIcon(p) {
    var k = normPlat(p) || "youtube";
    var box = 'viewBox="0 0 16 16" width="15" height="15" aria-hidden="true" focusable="false"';
    if (k === "linkedin") {
      return '<svg class="platmark" ' + box + '><rect width="16" height="16" rx="3" fill="#0A66C2"/>' +
        '<path fill="#fff" d="M4.2 6.3h1.7V12H4.2zM5 3.6a1 1 0 110 2 1 1 0 010-2zM7.2 6.3h1.6v.8c.25-.45.85-.9 1.7-.9 1.4 0 1.9.9 1.9 2.3V12h-1.7V9c0-.75-.25-1.2-.9-1.2-.6 0-.9.4-.9 1.2v3h-1.7z"/></svg>';
    }
    if (k === "instagram") {
      return '<svg class="platmark" ' + box + '>' +
        '<defs><linearGradient id="igg" x1="0" y1="1" x2="1" y2="0">' +
          '<stop offset="0" stop-color="#FDCB5C"/><stop offset=".45" stop-color="#E1306C"/>' +
          '<stop offset="1" stop-color="#7232BD"/></linearGradient></defs>' +
        '<rect width="16" height="16" rx="4.4" fill="url(#igg)"/>' +
        '<circle cx="8" cy="8" r="3.1" fill="none" stroke="#fff" stroke-width="1.35"/>' +
        '<circle cx="11.9" cy="4.2" r=".95" fill="#fff"/></svg>';
    }
    if (k === "twitter") {
      return '<svg class="platmark" ' + box + '><rect width="16" height="16" rx="3.4" fill="#000"/>' +
        '<path fill="#fff" d="M10.9 3.6h1.6l-3.5 4 4.1 5.4h-3.2l-2.5-3.3-2.9 3.3H2.9l3.7-4.3-3.9-5.1h3.3l2.3 3zm-.6 8.4h.9L6.2 4.5h-1z"/></svg>';
    }
    if (k === "tiktok") {
      return '<svg class="platmark" ' + box + '><rect width="16" height="16" rx="3.4" fill="#000"/>' +
        '<path fill="#fff" d="M9.6 3.1c.2 1.1.9 1.9 2 2.05V6.5c-.75.05-1.45-.15-2.05-.55v2.9a2.85 2.85 0 11-2.85-2.85c.15 0 .3 0 .45.03v1.4a1.5 1.5 0 101.05 1.42V3.1z"/></svg>';
    }
    if (k === "skool") {
      return '<svg class="platmark" ' + box + '><rect width="16" height="16" rx="4" fill="#F2B824"/>' +
        '<path fill="#17202A" d="M3.2 5.2l1.7-1.7 1.5 1.8h3.2l1.5-1.8 1.7 1.7-.7 6.1c-.1.8-.8 1.3-1.6 1.3h-5c-.8 0-1.5-.5-1.6-1.3z"/>' +
        '<circle cx="6.2" cy="8.2" r=".8" fill="#F2B824"/><circle cx="9.8" cy="8.2" r=".8" fill="#F2B824"/></svg>';
    }
    return '<svg class="platmark" ' + box + '><rect y="2.4" width="16" height="11.2" rx="3.1" fill="#FF0033"/>' +
      '<path fill="#fff" d="M6.5 5.4l4.4 2.6-4.4 2.6z"/></svg>';
  }

  function skoolMetric(v, kind) {
    var raw = String(v == null ? "" : v).trim();
    if (!raw) return "—";
    var n = Number(raw.replace(/[^0-9.-]/g, ""));
    if (!isFinite(n)) return raw;
    if (kind === "change") return (n < 0 ? "-$" : n > 0 ? "+$" : "$") + Math.abs(Math.round(n)).toLocaleString();
    return (kind === "money" ? "$" : "") + Math.round(n).toLocaleString();
  }

  function skoolPrice(v) {
    var raw = String(v == null ? "" : v).trim();
    if (!raw) return "—";
    if (raw.toLowerCase() === "free" || raw === "0") return "Free";
    return "$" + raw.replace(/^\$/, "") + "/month";
  }

